"use client";
import { useState, useRef, useEffect } from "react";

const APP_ID = "1089";
const SYMBOL = "R_75";

export default function Page() {
  const [token, setToken] = useState("");
    const [balance, setBalance] = useState(10000);
      const [realBal, setRealBal] = useState(0);
        const [mode, setMode] = useState<"demo"|"real">("demo");
          const [tick, setTick] = useState(0);
            const [stake, setStake] = useState(1);
              const [mult, setMult] = useState(200);
                const [logs, setLogs] = useState<string[]>(["Ready - Demo $10k. For REAL: paste a1- token from app.deriv.com/account/api-token"]);
                  const [openPos, setOpenPos] = useState<any>(null);
                    const wsRef = useRef<WebSocket|null>(null);
                      const propRef = useRef<any>(null);

                        const log = (m:string) => setLogs(l=>[`${new Date().toLocaleTimeString()} ${m}`,...l].slice(0,25));

                          useEffect(()=>{
                              const ws = new WebSocket(`wss://ws.derivws.com/websockets/v3?app_id=${APP_ID}`);
                                  ws.onopen = ()=> ws.send(JSON.stringify({ticks: SYMBOL}));
                                      ws.onmessage = (e)=>{
                                            const d = JSON.parse(e.data);
                                                  if(d.tick) setTick(d.tick.quote);
                                                        if(d.proposal_open_contract){
                                                                const c = d.proposal_open_contract;
                                                                        if(c.is_sold){
                                                                                  const profit = c.profit;
                                                                                            setBalance(b=>mode==="demo"? b+profit : b);
                                                                                                      if(mode==="real") setRealBal(c.account_balance || realBal);
                                                                                                                log(`${profit>=0?"WIN":"LOSS"} Closed P/L $${profit} Bal $${(mode==="demo"?balance+profit:realBal+profit).toFixed(2)}`);
                                                                                                                          setOpenPos(null);
                                                                                                                                  } else {
                                                                                                                                            setOpenPos(c);
                                                                                                                                                    }
                                                                                                                                                          }
                                                                                                                                                              };
                                                                                                                                                                  wsRef.current = ws;
                                                                                                                                                                      const saved = localStorage.getItem("deriv_token");
                                                                                                                                                                          if(saved) setToken(saved);
                                                                                                                                                                            },[]);

                                                                                                                                                                              const connectReal = () => {
                                                                                                                                                                                  if(!token || token.startsWith("pat_")){
                                                                                                                                                                                        log("ERROR: Use a1- token from app.deriv.com/account/api-token, NOT pat_");
                                                                                                                                                                                              return;
                                                                                                                                                                                                  }
                                                                                                                                                                                                      const ws = new WebSocket(`wss://ws.derivws.com/websockets/v3?app_id=${APP_ID}`);
                                                                                                                                                                                                          ws.onopen = ()=> ws.send(JSON.stringify({authorize: token}));
                                                                                                                                                                                                              ws.onmessage = (e)=>{
                                                                                                                                                                                                                    const d = JSON.parse(e.data);
                                                                                                                                                                                                                          if(d.authorize){
                                                                                                                                                                                                                                  setRealBal(d.authorize.balance);
                                                                                                                                                                                                                                          setBalance(d.authorize.balance);
                                                                                                                                                                                                                                                  setMode("real");
                                                                                                                                                                                                                                                          log(`REAL LIVE! Balance $${d.authorize.balance} ID ${d.authorize.loginid}`);
                                                                                                                                                                                                                                                                  // subscribe balance and ticks
                                                                                                                                                                                                                                                                          ws.send(JSON.stringify({balance:1, subscribe:1}));
                                                                                                                                                                                                                                                                                  ws.send(JSON.stringify({ticks: SYMBOL, subscribe:1}));
                                                                                                                                                                                                                                                                                          ws.send(JSON.stringify({proposal_open_contract:1, subscribe:1}));
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                      if(d.balance) setRealBal(d.balance.balance);
                                                                                                                                                                                                                                                                                                            if(d.proposal){
                                                                                                                                                                                                                                                                                                                    propRef.current = d.proposal;
                                                                                                                                                                                                                                                                                                                            log(`Proposal $${d.proposal.ask_price} → BUYING...`);
                                                                                                                                                                                                                                                                                                                                    ws.send(JSON.stringify({buy: d.proposal.id, price: d.proposal.ask_price}));
                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                if(d.buy){
                                                                                                                                                                                                                                                                                                                                                        log(`BOUGHT! Contract ${d.buy.contract_id} - Watch P/L`);
                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                    if(d.proposal_open_contract){
                                                                                                                                                                                                                                                                                                                                                                            if(d.proposal_open_contract.is_sold){
                                                                                                                                                                                                                                                                                                                                                                                      const p = d.proposal_open_contract;
                                                                                                                                                                                                                                                                                                                                                                                                setRealBal(p.account_balance || realBal);
                                                                                                                                                                                                                                                                                                                                                                                                          log(`CLOSED P/L $${p.profit} Balance $${p.account_balance}`);
                                                                                                                                                                                                                                                                                                                                                                                                                    setOpenPos(null);
                                                                                                                                                                                                                                                                                                                                                                                                                            } else setOpenPos(d.proposal_open_contract);
                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                        if(d.error) log("ERR: "+d.error.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                              if(d.tick) setTick(d.tick.quote);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                                                                                                                                                      wsRef.current = ws;
                                                                                                                                                                                                                                                                                                                                                                                                                                                          localStorage.setItem("deriv_token", token);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                              const buyReal = (dir:"MULTUP"|"MULTDOWN") => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const ws = wsRef.current;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if(!ws || mode!=="real") return log("Connect REAL first");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const req = {proposal:1, amount:stake, basis:"stake", contract_type:dir, currency:"USD", multiplier:mult, symbol:SYMBOL};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ws.send(JSON.stringify(req));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  log(`REAL ${dir} x${mult} $${stake} asking...`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const buyDemo = (dir:"up"|"down") => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if(openPos) return log("Close open first");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const entry = tick;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setOpenPos({entry, dir, stake, is_demo:true, profit:0});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      log(`DEMO ${dir.toUpperCase()} x${mult} $${stake} @ ${entry.toFixed(2)}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          let ticks=0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const iv = setInterval(()=>{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ticks++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const cur = tick + (Math.random()-0.5);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const diff = (cur-entry)*(dir==="up"?1:-1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const profit = diff*mult*0.01 - stake*0.05;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setOpenPos((p:any)=>({...p, current:cur, profit}));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if(ticks>8){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          clearInterval(iv);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const finalProfit = (Math.random()>0.45? stake*0.7 : -stake);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setBalance(b=>b+finalProfit);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  log(`${finalProfit>0?"WIN":"LOSS"} Demo P/L $${finalProfit.toFixed(2)} Bal $${(balance+finalProfit).toFixed(2)}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setOpenPos(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },800);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{background:"#000", color:"#0f0", minHeight:"100vh", padding:14, fontFamily:"monospace"}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h1 style={{fontSize:20, fontWeight:"bold"}}>PROFITLANCE {mode==="real"?"REAL 💰":"DEMO"} R_75 {tick.toFixed(2)}</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h2 style={{fontSize:26}}>Bal: ${mode==="real"?realBal.toFixed(2):balance.toFixed(2)} {openPos?`(P/L ${openPos.profit?.toFixed(2)||0})`:""}</h2>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {openPos && <div style={{background:openPos.profit>=0?"#003300":"#330000", padding:8, marginTop:8, border:"1px solid #0f0"}}>{openPos.dir||openPos.contract_type} Entry {openPos.entry||openPos.entry_tick} → {openPos.current?.toFixed(2)||tick.toFixed(2)} Profit ${openPos.profit?.toFixed(2)||"..."}</div>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{display:"flex", gap:6, marginTop:10}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button onClick={()=>{setMode("demo"); setBalance(10000); log("DEMO mode $10k")}} style={{flex:1, padding:10, background:mode==="demo"?"#0f0":"#222", color:mode==="demo"?"#000":"#0f0"}}>DEMO</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button onClick={()=>window.location.href=`https://oauth.deriv.com/oauth2/authorize?app_id=${APP_ID}&redirect_uri=${encodeURIComponent(window.location.origin)}`} style={{flex:1, padding:10, background:"#f00", color:"#fff"}}>LOGIN DERIV</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input value={token} onChange={e=>setToken(e.target.value)} placeholder="Paste a1- token for REAL trading" style={{width:"100%", marginTop:10, padding:10, background:"#111", color:"#0f0", border:"1px solid #333"}}/>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button onClick={connectReal} style={{width:"100%", marginTop:5, padding:10, background:"#333", color:"#0f0"}}>CONNECT REAL</button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{display:"flex", gap:8, marginTop:10}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label>Stake $ <input type="number" value={stake} onChange={e=>setStake(Number(e.target.value))} style={{width:60, background:"#111", color:"#0f0"}}/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <label>Mult <select value={mult} onChange={e=>setMult(Number(e.target.value))} style={{background:"#111", color:"#0f0"}}><option value={100}>x100</option><option value={200}>x200</option><option value={500}>x500</option><option value={1000}>x1000</option></select></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginTop:12}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button onClick={()=>mode==="demo"?buyDemo("up"):buyReal("MULTUP")} style={{padding:16, background:"#0a0", color:"#fff", fontWeight:"bold"}}>BUY UP x{mult}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button onClick={()=>mode==="demo"?buyDemo("down"):buyReal("MULTDOWN")} style={{padding:16, background:"#a00", color:"#fff", fontWeight:"bold"}}>SELL DOWN x{mult}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{marginTop:12, maxHeight:280, overflow:"auto", fontSize:11, borderTop:"1px solid #222", paddingTop:6}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {logs.map((l,i)=><div key={i} style={{borderBottom:"1px solid #111", padding:"3px 0"}}>{l}</div>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }